// CloudtainerML rev0030 — Gated bidirectional linear attention probe.
// Inspired by GBLA: local causal mixing, sequence-level key gating/forgetting, and gated normalization.
// Tiny symbolic retrieval/latency frontier, not a recommender reproduction.
#include <bits/stdc++.h>
using namespace std; static string q(const string&s){string o="\""; for(char c:s){if(c=='\"'||c=='\\')o+='\\'; if(c=='\n')o+="\\n"; else o+=c;} return o+'\"';}
struct Regime{string name; double long_range, locality, bidirectional_need, stale_noise, popularity, recurrence;};
struct Row{string regime,method; int history,budget; double quality,cost_frac,forget_error,local_miss,latency_proxy,regret,score;};
static double C(double x){return max(0.0,min(1.0,x));}
static Row eval(const Regime&r,string m,int H,int bp){double B=bp/100.0; double lengthFactor=log2(H/256.0+1.0); double quality=0,cost=0,forget=0,local=0,lat=0;
 if(m=="bidirectional_self_attention"){quality=.98-.04*r.stale_noise; cost=1.0; lat=1.0+0.22*lengthFactor;}
 else if(m=="plain_linear_attention"){quality=C(.46+.20*r.popularity+.16*r.recurrence-.22*r.long_range-.12*r.locality-.10*r.stale_noise); cost=.18+.12*B; forget=.32*r.long_range; local=.20*r.locality; lat=.20+.04*lengthFactor;}
 else if(m=="linear_plus_local_conv"){quality=C(.52+.18*r.popularity+.20*r.locality+.12*r.recurrence-.18*r.long_range-.10*r.stale_noise); cost=.22+.18*B; forget=.25*r.long_range; local=.08*(1-r.locality); lat=.24+.05*lengthFactor;}
 else if(m=="linear_key_gate"){quality=C(.50+.22*r.recurrence+.14*r.popularity-.08*r.stale_noise+.16*r.long_range-.08*r.locality); cost=.24+.14*B; forget=.10*r.long_range+.12*(1-r.recurrence); local=.18*r.locality; lat=.26+.05*lengthFactor;}
 else if(m=="gbla_style_all"){quality=C(.58+.18*r.locality+.22*r.recurrence+.18*r.long_range+.09*r.bidirectional_need-.12*r.stale_noise); cost=.29+.17*B; forget=.08*r.long_range+.08*(1-r.recurrence); local=.06*(1-r.locality); lat=.31+.06*lengthFactor;}
 else { // hybrid_sa_gbla_1to2
   quality=C(.66+.20*r.long_range+.16*r.locality+.18*r.bidirectional_need+.12*r.recurrence-.08*r.stale_noise); cost=.50+.18*B; forget=.04*r.long_range; local=.05; lat=.48+.08*lengthFactor; }
 double need=.58+.22*r.long_range+.12*r.bidirectional_need; double err=max(0.0,need-quality); double over=max(0.0,cost-B); double score=err+.36*over+.18*forget+.12*local+.08*lat; return {r.name,m,H,bp,quality,cost,forget,local,lat,0,score};}
int main(int argc,char**argv){string outp=argc>1?argv[1]:"REV0030_GATED_BIDIRECTIONAL_LINEAR_SMOKE.json"; vector<Regime> regs={{"long_range_retrieval",.92,.22,.88,.16,.34,.52},{"local_music_bursts",.28,.92,.55,.12,.70,.82},{"stale_popularity_noise",.44,.40,.66,.80,.88,.45},{"balanced_history",.62,.58,.64,.28,.50,.62},{"flat_random_history",.45,.25,.50,.55,.20,.25}}; vector<string> ms={"bidirectional_self_attention","plain_linear_attention","linear_plus_local_conv","linear_key_gate","gbla_style_all","hybrid_sa_gbla_1to2"}; vector<Row> rows; map<string,int>w,non; for(auto&r:regs) for(int H:{512,2048,8192,32768}) for(int b:{12,20,32,50,75}){vector<Row> cand; for(auto&m:ms)cand.push_back(eval(r,m,H,b)); double best=1e9; for(auto&x:cand)best=min(best,x.score); for(auto&x:cand){x.regret=max(0.0,x.score-best); rows.push_back(x);} auto bi=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){return a.score<b.score;}); w[bi->method]++; auto nb=min_element(cand.begin(),cand.end(),[](auto&a,auto&b){if(a.method=="bidirectional_self_attention")return false; if(b.method=="bidirectional_self_attention")return true; return a.score<b.score;}); non[nb->method]++;}
 ofstream f(outp); f<<fixed<<setprecision(6); f<<"{\n  \"project\": \"CloudtainerML\",\n  \"revision\": \"rev0030\",\n  \"probe\": \"gated_bidirectional_linear\",\n  \"summary\": {\n    \"row_count\": "<<rows.size()<<",\n    \"primary_metric\": {\"name\": \"score\", \"direction\": \"lower_is_better\", \"winner_field\": \"method\"},\n    \"winner_counts\": {"; bool first=true; for(auto&kv:w){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"nonoracle_winner_counts\": {"; first=true; for(auto&kv:non){if(!first)f<<", "; first=false; f<<q(kv.first)<<": "<<kv.second;} f<<"},\n    \"interpretation\": \"GBLA-style local+gate+norm hybrids are attractive when recurrence/locality coexist with long histories; full bidirectional attention remains the upper quality anchor when budget permits.\",\n    \"screen_regret_fields\": [\"quality\",\"cost_frac\",\"forget_error\",\"local_miss\",\"latency_proxy\",\"regret\",\"score\"]\n  },\n  \"rows\": [\n"; for(size_t i=0;i<rows.size();++i){auto&r=rows[i]; f<<"    {\"regime\": "<<q(r.regime)<<", \"method\": "<<q(r.method)<<", \"history\": "<<r.history<<", \"budget_pct\": "<<r.budget<<", \"quality\": "<<r.quality<<", \"cost_frac\": "<<r.cost_frac<<", \"forget_error\": "<<r.forget_error<<", \"local_miss\": "<<r.local_miss<<", \"latency_proxy\": "<<r.latency_proxy<<", \"regret\": "<<r.regret<<", \"score\": "<<r.score<<"}"<<(i+1<rows.size()?",":"")<<"\n";} f<<"  ]\n}\n";}
